using System.Buffers.Binary;using System.Diagnostics;using System.Net;using System.Net.Sockets;using System.Security.Cryptography;using System.Text;using System.Text.Json;using System.Text.Json.Nodes;
namespace Orbit.Core;
public static class LocalSkins {
 public const string AgentHash="9c7f4343e6c82034958ffb48c14a2cb0c85928be7283103ce17da00c6d5a7b10";
 public static string SkinPath=>Path.Combine(LauncherSettings.DataRoot,"skins","selected.png");
 public static (int Width,int Height) Validate(byte[] png){if(png.Length<33||png.Length>2*1024*1024||!png.AsSpan(0,8).SequenceEqual(new byte[]{137,80,78,71,13,10,26,10})||Encoding.ASCII.GetString(png,12,4)!="IHDR")throw new InvalidDataException("Нужен PNG-скин размером 64×64 или 64×32.");int w=BinaryPrimitives.ReadInt32BigEndian(png.AsSpan(16,4)),h=BinaryPrimitives.ReadInt32BigEndian(png.AsSpan(20,4));if(w!=64||h is not (32 or 64))throw new InvalidDataException("Поддерживаются скины 64×64 и старые 64×32.");return(w,h);}
 public static string Agent(string root){Directory.CreateDirectory(root);string path=Path.Combine(root,"authlib-injector-1.2.8.jar");if(File.Exists(path)&&Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))).Equals(AgentHash,StringComparison.OrdinalIgnoreCase))return path;using var source=typeof(LocalSkins).Assembly.GetManifestResourceStream("Orbit.SkinAgent.jar")??throw new IOException("Компонент скинов отсутствует.");using var bytes=new MemoryStream();source.CopyTo(bytes);byte[] data=bytes.ToArray();if(!Convert.ToHexString(SHA256.HashData(data)).Equals(AgentHash,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Компонент скинов повреждён.");File.WriteAllBytes(path+".new",data);File.Move(path+".new",path,true);return path;}
 public static async Task<SkinSession> PrepareAsync(LauncherSettings s,string executable){if(!File.Exists(SkinPath))throw new IOException("Выбранный скин не найден. Выбери PNG заново.");string dir=Path.Combine(LauncherSettings.DataRoot,"skin-sessions",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);byte[] png=File.ReadAllBytes(SkinPath);var size=Validate(png);File.WriteAllBytes(Path.Combine(dir,"skin.png"),png);var config=new SkinConfig(s.Nickname,LaunchEngine.OfflineUuid(s.Nickname),s.SkinModel=="slim"&&size.Height==64?"slim":"default");File.WriteAllText(Path.Combine(dir,"config.json"),JsonSerializer.Serialize(config));string jar=Agent(Path.Combine(LauncherSettings.DataRoot,"components"));var start=new ProcessStartInfo(executable){UseShellExecute=false,CreateNoWindow=true};start.ArgumentList.Add("--skin-host");start.ArgumentList.Add(dir);var helper=Process.Start(start)??throw new IOException("Сервис скина не запустился.");for(int i=0;i<150;i++){if(helper.HasExited)throw new IOException("Сервис скина завершился: "+(File.Exists(Path.Combine(dir,"error.txt"))?File.ReadAllText(Path.Combine(dir,"error.txt")):"ошибка запуска"));string ready=Path.Combine(dir,"ready.txt");if(File.Exists(ready)){string url=File.ReadAllText(ready);if(Uri.TryCreate(url,UriKind.Absolute,out var u)&&u.Host=="127.0.0.1"&&u.Scheme=="http")return new SkinSession(dir,url,jar,helper);}await Task.Delay(100);}try{helper.Kill();}catch{}throw new IOException("Сервис скина не ответил вовремя.");}
}
public sealed record SkinConfig(string Nickname,string Uuid,string Model);
public sealed class SkinSession:IDisposable {
 readonly string dir;readonly Process helper;public string Url{get;}public string AgentPath{get;}
 public SkinSession(string folder,string url,string agent,Process process){dir=folder;Url=url;AgentPath=agent;helper=process;}
 public void Apply(LaunchPlan plan){plan.Arguments.InsertRange(0,new[]{"-javaagent:"+AgentPath+"="+Url,"-Dauthlibinjector.mojangNamespace=disabled","-Dauthlibinjector.noShowServerName","-Dauthlibinjector.noLogFile","-Dauthlibinjector.mojangAntiFeatures=enabled"});}
 public void Attach(Process game){string pid=Path.Combine(dir,"game.pid");File.WriteAllText(pid+".new",game.Id.ToString()+"|"+game.StartTime.ToUniversalTime().Ticks);File.Move(pid+".new",pid,true);}
 public void Dispose(){try{File.WriteAllText(Path.Combine(dir,"stop"),"");}catch{}helper.Dispose();}
}
public sealed class SkinServer:IDisposable {
 readonly TcpListener listener=new(IPAddress.Loopback,0);readonly RSA signing=RSA.Create(2048);readonly byte[] png;readonly SkinConfig config;readonly string prefix="/"+Guid.NewGuid().ToString("N");readonly CancellationTokenSource stop=new();readonly string hash;
 public string Url{get;private set;}="";public SkinServer(SkinConfig c,byte[] image){config=c;png=image;LocalSkins.Validate(image);hash=Convert.ToHexString(SHA256.HashData(png)).ToLowerInvariant();}
 public void Start(){listener.Start();Url="http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port+prefix+"/";_ = Accept();}
 async Task Accept(){while(!stop.IsCancellationRequested)try{var client=await listener.AcceptTcpClientAsync(stop.Token);_ = Handle(client);}catch(OperationCanceledException){break;}catch(ObjectDisposedException){break;}catch(SocketException){if(stop.IsCancellationRequested)break;}}
 object Identity()=>new{id=config.Uuid,name=config.Nickname};
 public object Profile(){string value=Convert.ToBase64String(JsonSerializer.SerializeToUtf8Bytes(new{timestamp=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),profileId=config.Uuid,profileName=config.Nickname,textures=new{SKIN=new{url=Url+"textures/"+hash+".png",metadata=new{model=config.Model}}}}));return new{id=config.Uuid,name=config.Nickname,properties=new[]{new{name="textures",value,signature=Convert.ToBase64String(signing.SignData(Encoding.UTF8.GetBytes(value),HashAlgorithmName.SHA1,RSASignaturePadding.Pkcs1))}}};}
 public object Metadata()=>new{meta=new Dictionary<string,object>{{"serverName","ORBIT Local Skin"},{"implementationName","ORBIT"},{"feature.no_mojang_namespace",true},{"feature.enable_profile_key",false}},skinDomains=new[]{"127.0.0.1"},signaturePublickey=signing.ExportSubjectPublicKeyInfoPem()};
 async Task Handle(TcpClient client){using(client){try{using var timeout=CancellationTokenSource.CreateLinkedTokenSource(stop.Token);timeout.CancelAfter(TimeSpan.FromSeconds(10));var ct=timeout.Token;var stream=client.GetStream();var bytes=new List<byte>();byte[] one=new byte[1];while(bytes.Count<16384){if(await stream.ReadAsync(one,ct)==0)return;bytes.Add(one[0]);int n=bytes.Count;if(n>=4&&bytes[n-4]==13&&bytes[n-3]==10&&bytes[n-2]==13&&bytes[n-1]==10)break;}string head=Encoding.ASCII.GetString(bytes.ToArray());var lines=head.Split("\r\n");var first=lines[0].Split(' ');if(first.Length<2)return;string path=first[1].Split('?')[0];int len=0;foreach(var line in lines)if(line.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase))int.TryParse(line[15..].Trim(),out len);if(len<0||len>65536)return;byte[] body=new byte[len];await stream.ReadExactlyAsync(body,ct);int status=200;object? result=null;byte[]? binary=null;
 if(!path.StartsWith(prefix+"/",StringComparison.Ordinal))status=404;else{path=path[(prefix.Length+1)..].TrimEnd('/');if(path=="")result=Metadata();else if(first[0]=="GET"&&path=="textures/"+hash+".png")binary=png;else if(first[0]=="GET"&&path=="sessionserver/session/minecraft/profile/"+config.Uuid)result=Profile();else if(first[0]=="GET"&&path.StartsWith("api/users/profiles/minecraft/")&&Uri.UnescapeDataString(path[29..]).Equals(config.Nickname,StringComparison.OrdinalIgnoreCase))result=Identity();else if(first[0]=="POST"&&path=="api/profiles/minecraft"){var names=JsonSerializer.Deserialize<string[]>(body)??Array.Empty<string>();result=names.Any(n=>n.Equals(config.Nickname,StringComparison.OrdinalIgnoreCase))?new[]{Identity()}:Array.Empty<object>();}else if(path.EndsWith("/join",StringComparison.Ordinal))status=403;
 // A cosmetic-only local profile has no Minecraft Services account credentials.
 // 401 lets authlib throw AuthenticationException and Minecraft select its offline service.
 // 204 incorrectly looks successful and crashes authlib 2.x on a null privileges response.
 else if(path.StartsWith("minecraftservices/",StringComparison.Ordinal)||path.StartsWith("authserver/",StringComparison.Ordinal)){status=401;result=new{error="Unauthorized",errorMessage="Online account services are unavailable for a local cosmetic profile."};}
 else status=204;}
 byte[] data=binary??(result==null?Array.Empty<byte>():JsonSerializer.SerializeToUtf8Bytes(result));string headers=$"HTTP/1.1 {status} {(status==200?"OK":status==204?"No Content":status==401?"Unauthorized":status==404?"Not Found":"Forbidden")}\r\nContent-Type: {(binary!=null?"image/png":"application/json")}\r\nContent-Length: {data.Length}\r\nConnection: close\r\nCache-Control: no-store\r\n\r\n";await stream.WriteAsync(Encoding.ASCII.GetBytes(headers),ct);await stream.WriteAsync(data,ct);
 }catch(Exception e)when(e is IOException or OperationCanceledException or JsonException or SocketException){}}}
 public static async Task HostAsync(string dir){try{var c=JsonSerializer.Deserialize<SkinConfig>(await File.ReadAllTextAsync(Path.Combine(dir,"config.json")))??throw new IOException("Skin config missing");using var host=new SkinServer(c,await File.ReadAllBytesAsync(Path.Combine(dir,"skin.png")));host.Start();string ready=Path.Combine(dir,"ready.txt");File.WriteAllText(ready+".new",host.Url);File.Move(ready+".new",ready,true);var wait=Stopwatch.StartNew();Process? game=null;while(!File.Exists(Path.Combine(dir,"stop"))){string pidFile=Path.Combine(dir,"game.pid");if(game==null&&File.Exists(pidFile)){var parts=File.ReadAllText(pidFile).Split('|');try{game=Process.GetProcessById(int.Parse(parts[0]));if(game.StartTime.ToUniversalTime().Ticks!=long.Parse(parts[1]))break;}catch(ArgumentException){break;}}if(game!=null&&game.HasExited)break;if(game==null&&wait.Elapsed>TimeSpan.FromSeconds(60))break;await Task.Delay(500);}game?.Dispose();}catch(Exception e){try{File.WriteAllText(Path.Combine(dir,"error.txt"),e.Message);}catch{}}}
 public void Dispose(){stop.Cancel();listener.Stop();signing.Dispose();stop.Dispose();}
}
